// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.17;

import {Ownable2StepUpgradeable} from "@openzeppelin/contracts-upgradeable-4.9.6/access/Ownable2StepUpgradeable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable-4.9.6/proxy/utils/UUPSUpgradeable.sol";

import {OracleManagement, IPriceOracle, OwnableCheck} from "./OracleManagement.sol";
import {ProtocolTreasuryManagement} from "./ProtocolTreasuryManagement.sol";
import {SystemSettings} from "./SystemSettings.sol";
import {TokenManagement} from "./TokenManagement.sol";
import {ProtocolFeeManagement} from "./ProtocolFeeManagement.sol";
import {SolverManagement} from "./SolverManagement.sol";

import {RewardTargetManagement} from "./RewardTargetManagement.sol";

/**
 * @title MainContract
 * @dev Main contract integrating all management functionalities with access control.
 */
contract ProtocolConfig is
  Ownable2StepUpgradeable,
  UUPSUpgradeable,
  OracleManagement,
  ProtocolTreasuryManagement,
  SystemSettings,
  TokenManagement,
  ProtocolFeeManagement,
  SolverManagement,
  RewardTargetManagement
{
  /// @custom:oz-upgrades-unsafe-allow constructor
  constructor() {
    _disableInitializers();
  }

  // Implement the OwnableUpgradeable initialization.
  function initialize(
    address _velvetTreasury,
    address _oracle
  ) external initializer {
    __Ownable2Step_init();
    __UUPSUpgradeable_init();
    __OracleManagement_init(_oracle);
    __TreasuryManagement_init(_velvetTreasury);
    __SystemSettings_init();
    __TokenManagement_init(_oracle);
    __FeeManagement_init();
  }

  function _owner() internal view override(OwnableCheck) returns (address) {
    return owner();
  }

  // Override the onlyOwner modifier to specify it overrides from OwnableUpgradeable.
  function _isOwner()
    internal
    view
    override(OwnableCheck)
    onlyOwner
    returns (bool)
  {
    return true;
  }

  /**
   * @notice Authorizes upgrade for this contract
   * @param newImplementation Address of the new implementation
   */
  function _authorizeUpgrade(
    address newImplementation
  ) internal override onlyOwner {
    // Intentionally left empty as required by an abstract contract
  }
}

contracts/config/protocol/ProtocolFeeMan.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.17;

import {OwnableCheck} from "./OwnableCheck.sol";

import {ErrorLibrary} from "../../library/ErrorLibrary.sol";
import {Initializable} from "@openzeppelin/contracts-upgradeable-4.9.6/proxy/utils/Initializable.sol";

/**
 * @title FeeManagement
 * @notice Allows configuration of fees within the platform, including protocol fees and streaming fees.
 * These fees are critical for the platform's economic model and compensating platform operators and participants.
 */
abstract contract ProtocolFeeManagement is OwnableCheck, Initializable {
  uint256 public maxManagementFee;
  uint256 public maxPerformanceFee;
  uint256 public maxEntryFee;
  uint256 public maxExitFee;
  uint256 public protocolFee;
  uint256 public protocolStreamingFee;

  event ProtocolFeeUpdated(uint256 indexed newProtocolFee);
  event ProtocolStreamingFeeUpdated(uint256 indexed newProtocolStreamingFee);

  /**
   * @dev Sets default fee percentages and system limits.
   */
  function __FeeManagement_init() internal onlyInitializing {
    protocolFee = 2500; // 25% of management fee
    protocolStreamingFee = 30; // 0.3% annual
    maxManagementFee = 1000; // 10% annual
    maxPerformanceFee = 3000; // 30% of profit
    maxEntryFee = 500; // 5%
    maxExitFee = 500; // 5%
  }

  function updateProtocolFee(
    uint256 _newProtocolFee
  ) external onlyProtocolOwner {
    if (_newProtocolFee > 5_000 || _newProtocolFee == protocolFee)
      revert ErrorLibrary.InvalidProtocolFee();
    protocolFee = _newProtocolFee;
    emit ProtocolFeeUpdated(_newProtocolFee);
  }

  function updateProtocolStreamingFee(
    uint256 _newProtocolStreamingFee
  ) external onlyProtocolOwner {
    if (
      _newProtocolStreamingFee > 100 ||
      _newProtocolStreamingFee == protocolStreamingFee
    ) revert ErrorLibrary.InvalidProtocolStreamingFee();

    protocolStreamingFee = _newProtocolStreamingFee;
    emit ProtocolStreamingFeeUpdated(_newProtocolStreamingFee);
  }
}

contracts/config/protocol/ProtocolTreasu.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.17;

import {ErrorLibrary} from "../../library/ErrorLibrary.sol";

import {OwnableCheck} from "./OwnableCheck.sol";
import {Initializable} from "@openzeppelin/contracts-upgradeable-4.9.6/proxy/utils/Initializable.sol";

/**
 * @title TreasuryManagement
 * @notice Manages the treasury's address, facilitating updates to the treasury location.
 * This is crucial for directing fees and other financial transactions.
 */
abstract contract ProtocolTreasuryManagement is OwnableCheck, Initializable {
  address public velvetTreasury;

  event TreasuryUpdated(address indexed newTreasury);

  /**
   * @dev Initializes the contract by setting the initial treasury address.
   * @param _velvetTreasury Initial address of the velvet' treasury.
   */
  function __TreasuryManagement_init(
    address _velvetTreasury
  ) internal onlyInitializing {
    // Ensures the treasury address is not the zero address.
    _updateVelvetTreasury(_velvetTreasury);
  }

  /**
   * @dev Updates the address of the treasury.
   * @param _newVelvetTreasury New address for the treasury.
   */
  function updateVelvetTreasury(
    address _newVelvetTreasury
  ) external onlyProtocolOwner {
    _updateVelvetTreasury(_newVelvetTreasury);
    emit TreasuryUpdated(_newVelvetTreasury);
  }

  function _updateVelvetTreasury(address _newTreasury) internal {
    if (_newTreasury == address(0))
      revert ErrorLibrary.ZeroAddressTreasury();
    if(_newTreasury == velvetTreasury)
      revert ErrorLibrary.PreviousTreasuryAddress();

    velvetTreasury = _newTreasury;
  }
}

contracts/config/protocol/RewardTargetMa.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.17;

import {ErrorLibrary} from "../../library/ErrorLibrary.sol";
import {OwnableCheck} from "./OwnableCheck.sol";

/**
 * @title RewardTargetManagement
 * @notice Manages reward claim target addresses, enabling or disabling them as needed for platform operations.
 * These addresses play a crucial role in claiming rewards from different sources on the platform.
 */
abstract contract RewardTargetManagement is OwnableCheck {
  mapping(address => bool) public enabledRewardTargetAddress;

  event RewardTargetEnabled(address indexed rewardTargetAddress);
  event RewardTargetDisabled(address indexed rewardTargetAddress);
  event RewardTargetsEnabled(address[] rewardTargetAddresses);

  /**
   * @notice Checks if a reward target address is enabled.
   * @param _rewardTargetAddress The address of the reward target to check.
   * @return Boolean indicating if the reward target address is enabled.
   */
  function isRewardTargetEnabled(
    address _rewardTargetAddress
  ) external view virtual returns (bool) {
    return enabledRewardTargetAddress[_rewardTargetAddress];
  }

  /**
   * @notice Internal function to enable a reward target address.
   * @param _rewardTargetAddress The address of the reward target to enable.
   * @dev This function can only be called by the protocol owner.
   * @dev Reverts if the provided address is invalid (address(0)).
   */
  function _enableRewardTarget(
    address _rewardTargetAddress
  ) internal onlyProtocolOwner {
    if (_rewardTargetAddress == address(0))
      revert ErrorLibrary.InvalidAddress();
    enabledRewardTargetAddress[_rewardTargetAddress] = true;
  }

  /**
   * @notice Enables a reward target address by setting its status to true in the mapping.
   * @param _rewardTargetAddress The address of the reward target to enable.
   * @dev This function can only be called by the protocol owner.
   * @dev Reverts if the provided address is invalid (address(0)).
   */
  function enableRewardTarget(
    address _rewardTargetAddress
  ) external onlyProtocolOwner {
    _enableRewardTarget(_rewardTargetAddress);
    emit RewardTargetEnabled(_rewardTargetAddress);
  }

  /**
   * @notice Enables multiple reward target addresses by setting their status to true in the mapping.
   * @param _rewardTargetAddresses The addresses of the reward targets to enable.
   * @dev This function can only be called by the protocol owner.
   * @dev Reverts if the provided address array is empty.
   */
  function enableRewardTargets(
    address[] calldata _rewardTargetAddresses
  ) external onlyProtocolOwner {
    uint256 rewardTargetLength = _rewardTargetAddresses.length;
    if (rewardTargetLength == 0) revert ErrorLibrary.InvalidLength();
    for (uint256 i; i < rewardTargetLength; i++) {
      _enableRewardTarget(_rewardTargetAddresses[i]);
    }

    emit RewardTargetsEnabled(_rewardTargetAddresses);
  }

  /**
   * @notice Disables a reward target address by setting its status to false in the mapping.
   * @param _rewardTargetAddress The address of the reward target to disable.
   * @dev This function can only be called by the protocol owner.
   * @dev Reverts if the provided address is invalid (address(0)).
   */
  function disableRewardTarget(
    address _rewardTargetAddress
  ) external virtual onlyProtocolOwner {
    if (_rewardTargetAddress == address(0))
      revert ErrorLibrary.InvalidAddress();

    enabledRewardTargetAddress[_rewardTargetAddress] = false;
    emit RewardTargetDisabled(_rewardTargetAddress);
  }
}

